const http2 = require('http2');
const fs = require('fs');
const jwt = require('jsonwebtoken');
const { OrderDispatch } = require('../models/orders');

const server = http2.createSecureServer({
  key: fs.readFileSync('/etc/ssl/logistics.key'),
  cert: fs.readFileSync('/etc/ssl/logistics.crt')
});

server.on('stream', async (stream, headers) => {
  const url = new URL(headers[':path'], 'https://logistics.courier.internal');

  if (url.pathname === '/orders/track') {
    const orderId = url.searchParams.get('orderId');

    const authHeader = headers['authorization'];
    if (!authHeader) {
      stream.respond({ ':status': 401 });
      return stream.end('Unauthorized');
    }

    let customer;
    try {
      customer = jwt.verify(authHeader.replace('Bearer ', ''), process.env.JWT_SECRET);
    } catch {
      stream.respond({ ':status': 401 });
      return stream.end('Invalid credentials');
    }

    const dispatch = await OrderDispatch.findOne({ where: { orderId } });
    if (!dispatch || dispatch.customerId !== customer.id) {
      stream.respond({ ':status': 403 });
      return stream.end('Access denied: order not owned by authenticated customer');
    }

    if (orderId && stream.pushAllowed) {
      stream.pushStream({ ':path': `/api/orders/${orderId}/shipping-details.json` }, async (err, pushStream) => {
        if (err) return;
        pushStream.respond({ ':status': 200, 'content-type': 'application/json' });
        pushStream.end(JSON.stringify({
          orderId,
          deliveryAddress: dispatch.deliveryAddress,
          gateAccessPin: dispatch.gateAccessPin,
          recipientPhone: dispatch.recipientPhone
        }));
      });
    }

    stream.respond({ ':status': 200, 'content-type': 'text/html' });
    stream.end('<html><body>Tracking view ready</body></html>');
  }
});

server.listen(8445);
